package org.sleepwell.app;

import org.json.*;
import java.util.*;

final class ChallengeRoutineJson {
    static JSONArray encode(ChallengeRoutine routine){if(routine.randomCount>0)return RandomChallenges.encode(routine);JSONArray array=new JSONArray();try{for(ChallengeRoutine.Task task:routine.tasks){JSONObject row=new JSONObject().put("type",task.type).put("rounds",task.rounds);if(task.type.equals("Object recognition"))row.put("objectTarget",ObjectTargetJson.encode(task.objectTarget));if(task.type.equals("Dream journal"))row.put("minimum",task.journalMinimum);if(task.type.equals("Walk"))row.put("steps",task.targetSteps);if(task.type.equals("Math")&&!task.math.equals(MathSettings.LEGACY))row.put("math",MathSettingsJson.encode(task.math));if(task.type.equals("Picture match"))row.put("picture",PictureReferenceJson.encode(task.picture));if(task.type.equals("QR code"))row.put("code",MorningCodeJson.encode(task.code));array.put(row);}}catch(JSONException impossible){throw new IllegalStateException(impossible);}return array;}
    static ChallengeRoutine decode(JSONArray array)throws JSONException{if(array==null)throw new JSONException("Missing challenge routine");if(array.length()>0&&RandomChallenges.TYPE.equals(array.optJSONObject(0)==null?null:array.optJSONObject(0).optString("type")))return RandomChallenges.decode(array);List<ChallengeRoutine.Task> tasks=new ArrayList<>();if(array.length()>ChallengeRoutine.LIMIT)throw new JSONException("Too many challenge tasks");try{for(int n=0;n<array.length();n++){JSONObject task=array.getJSONObject(n);Object type=task.get("type"),rounds=task.get("rounds");if(!(type instanceof String)||!(rounds instanceof Number))throw new JSONException("Challenge type must be text and rounds must be an integer");double count=((Number)rounds).doubleValue();if(!Double.isFinite(count)||count!=Math.rint(count)||count<1||count>6)throw new JSONException("Challenge rounds must be an integer from 1 to 6");int target=0;if(type.equals("Walk")){Object steps=task.get("steps");if(!(steps instanceof Number)||!Double.isFinite(((Number)steps).doubleValue())||((Number)steps).doubleValue()!=Math.rint(((Number)steps).doubleValue()))throw new JSONException("Walk steps must be an integer");double value=((Number)steps).doubleValue();if(value<5||value>100)throw new JSONException("Choose 5–100 steps");target=(int)value;}MathSettings math=MathSettings.LEGACY;if(task.has("math")){if(!type.equals("Math"))throw new JSONException("Arithmetic settings belong only to a Math task");math=MathSettingsJson.decode(task.get("math"));}MorningCode code=null;if(task.has("code")){if(!type.equals("QR code"))throw new JSONException("Morning codes belong only to QR tasks");code=MorningCodeJson.decode(task.get("code"));}if(type.equals("QR code")&&code==null)throw new JSONException("Enroll a morning code first");int minimum=JournalRule.DEFAULT;if(task.has("minimum")){if(!type.equals("Dream journal"))throw new JSONException("Journal minimum belongs only to a journal task");Object raw=task.get("minimum");if(!(raw instanceof Number)||!Double.isFinite(((Number)raw).doubleValue())||((Number)raw).doubleValue()!=Math.rint(((Number)raw).doubleValue())||((Number)raw).doubleValue()<40||((Number)raw).doubleValue()>240||!JournalRule.MINIMUMS.contains(((Number)raw).intValue()))throw new JSONException("Invalid journal minimum");minimum=((Number)raw).intValue();}ObjectTarget objectTarget=null;if(task.has("objectTarget")){if(!type.equals("Object recognition"))throw new JSONException("Object targets belong only to Object recognition tasks");objectTarget=ObjectTargetJson.decode(task.get("objectTarget"));}if(type.equals("Object recognition")&&(objectTarget==null||task.length()!=3||count!=1))throw new JSONException("Choose one explicit object target");PictureReference picture=null;if(task.has("picture")){if(!type.equals("Picture match"))throw new JSONException("Picture references belong only to Picture match tasks");picture=PictureReferenceJson.decode(task.get("picture"));}if(type.equals("Picture match")){if(picture==null||task.length()!=3)throw new JSONException("Enroll one explicit picture reference");}if((type.equals("Laughter")||type.equals("Loud sound")||type.equals(PhraseRule.TYPE)||type.equals("Jumping")||type.equals("Smile")||type.equals("Pose")||type.equals("Light")||type.equals("Type code")||type.equals("Camera light")||type.equals("Spin around")||type.equals("Musical note"))&&task.length()!=2)throw new JSONException("This challenge uses only type and rounds");tasks.add(new ChallengeRoutine.Task((String)type,(int)count,target,math,code,minimum,picture,objectTarget));}return new ChallengeRoutine(tasks);}catch(IllegalArgumentException error){throw new JSONException(error.getMessage());}}
}
